        const double clhs70 =     -DeltaDOperator[19](0,0)*clhs12 - DeltaDOperator[19](0,1)*clhs13 - DeltaDOperator[19](0,2)*clhs14 + DeltaMOperator[19](0,0)*clhs8 + DeltaMOperator[19](0,1)*clhs9 + DeltaMOperator[19](0,2)*clhs10 + DeltaMOperator[19](0,3)*clhs11;
        const double clhs71 =     -DeltaDOperator[19](0,0)*clhs4 - DeltaDOperator[19](0,1)*clhs5 - DeltaDOperator[19](0,2)*clhs6 + DeltaMOperator[19](0,0)*clhs0 + DeltaMOperator[19](0,1)*clhs1 + DeltaMOperator[19](0,2)*clhs2 + DeltaMOperator[19](0,3)*clhs3 + MOperator(0,3);
