template<>
void AugmentedLagrangianMethodFrictionlessComponentsMortarContactCondition<2,2, false, 2>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 12; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 2, 2>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 2, 2>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 2, 2>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 2, 2>& X2 = rDerivativeData.X2;

    const BoundedMatrix<double, 2, 2> LM = MortarUtilities::GetVariableMatrix<2, 2>(r_geometry, VECTOR_LAGRANGE_MULTIPLIER, 0);

    const BoundedMatrix<double, 2, 2>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 2> DynamicFactor = MortarUtilities::GetVariableVector<2>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 2>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 2, 2>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 2, 2>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[0];

        rLocalRHS[8]+=-LM(0,0)*crhs0;
        rLocalRHS[9]+=-LM(0,1)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(0,0)*(DOperator(0,0)*(X1(0,0) + u1(0,0)) + DOperator(0,1)*(X1(1,0) + u1(1,0)) - MOperator(0,0)*(X2(0,0) + u2(0,0)) - MOperator(0,1)*(X2(1,0) + u2(1,0))) + NormalSlave(0,1)*(DOperator(0,0)*(X1(0,1) + u1(0,1)) + DOperator(0,1)*(X1(1,1) + u1(1,1)) - MOperator(0,0)*(X2(0,1) + u2(0,1)) - MOperator(0,1)*(X2(1,1) + u2(1,1)));
        const double crhs1 =     NormalSlave(0,0)*crhs0;
        const double crhs2 =     LM(0,0)*ScaleFactor - PenaltyParameter[0]*crhs1;
        const double crhs3 =     DynamicFactor[0]*MOperator(0,0);
        const double crhs4 =     NormalSlave(0,1)*crhs0;
        const double crhs5 =     LM(0,1)*ScaleFactor - PenaltyParameter[0]*crhs4;
        const double crhs6 =     DynamicFactor[0]*MOperator(0,1);
        const double crhs7 =     DOperator(0,0)*DynamicFactor[0];
        const double crhs8 =     DOperator(0,1)*DynamicFactor[0];
        const double crhs9 =     1.0/PenaltyParameter[0];
        const double crhs10 =     LM(0,0)*NormalSlave(0,0) + LM(0,1)*NormalSlave(0,1);
        const double crhs11 =     LM(0,1) - NormalSlave(0,1)*crhs10;
        const double crhs12 =     NormalSlave(0,0)*NormalSlave(0,1);
        const double crhs13 =     LM(0,0) - NormalSlave(0,0)*crhs10;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs2*crhs6;
        rLocalRHS[3]+=-crhs5*crhs6;
        rLocalRHS[4]+=crhs2*crhs7;
        rLocalRHS[5]+=crhs5*crhs7;
        rLocalRHS[6]+=crhs2*crhs8;
        rLocalRHS[7]+=crhs5*crhs8;
        rLocalRHS[8]+=ScaleFactor*(ScaleFactor*crhs9*(crhs11*crhs12 - crhs13*(1 - std::pow(NormalSlave(0,0), 2))) - crhs1);
        rLocalRHS[9]+=ScaleFactor*(ScaleFactor*crhs9*(-crhs11*(1 - std::pow(NormalSlave(0,1), 2)) + crhs12*crhs13) - crhs4);
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[1];

        rLocalRHS[10]+=-LM(1,0)*crhs0;
        rLocalRHS[11]+=-LM(1,1)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(1,0)*(DOperator(1,0)*(X1(0,0) + u1(0,0)) + DOperator(1,1)*(X1(1,0) + u1(1,0)) - MOperator(1,0)*(X2(0,0) + u2(0,0)) - MOperator(1,1)*(X2(1,0) + u2(1,0))) + NormalSlave(1,1)*(DOperator(1,0)*(X1(0,1) + u1(0,1)) + DOperator(1,1)*(X1(1,1) + u1(1,1)) - MOperator(1,0)*(X2(0,1) + u2(0,1)) - MOperator(1,1)*(X2(1,1) + u2(1,1)));
        const double crhs1 =     NormalSlave(1,0)*crhs0;
        const double crhs2 =     LM(1,0)*ScaleFactor - PenaltyParameter[1]*crhs1;
        const double crhs3 =     DynamicFactor[1]*MOperator(1,0);
        const double crhs4 =     NormalSlave(1,1)*crhs0;
        const double crhs5 =     LM(1,1)*ScaleFactor - PenaltyParameter[1]*crhs4;
        const double crhs6 =     DynamicFactor[1]*MOperator(1,1);
        const double crhs7 =     DOperator(1,0)*DynamicFactor[1];
        const double crhs8 =     DOperator(1,1)*DynamicFactor[1];
        const double crhs9 =     1.0/PenaltyParameter[1];
        const double crhs10 =     LM(1,0)*NormalSlave(1,0) + LM(1,1)*NormalSlave(1,1);
        const double crhs11 =     LM(1,1) - NormalSlave(1,1)*crhs10;
        const double crhs12 =     NormalSlave(1,0)*NormalSlave(1,1);
        const double crhs13 =     LM(1,0) - NormalSlave(1,0)*crhs10;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs2*crhs6;
        rLocalRHS[3]+=-crhs5*crhs6;
        rLocalRHS[4]+=crhs2*crhs7;
        rLocalRHS[5]+=crhs5*crhs7;
        rLocalRHS[6]+=crhs2*crhs8;
        rLocalRHS[7]+=crhs5*crhs8;
        rLocalRHS[10]+=ScaleFactor*(ScaleFactor*crhs9*(crhs11*crhs12 - crhs13*(1 - std::pow(NormalSlave(1,0), 2))) - crhs1);
        rLocalRHS[11]+=ScaleFactor*(ScaleFactor*crhs9*(-crhs11*(1 - std::pow(NormalSlave(1,1), 2)) + crhs12*crhs13) - crhs4);
    }
}

