template<>
void AugmentedLagrangianMethodFrictionlessComponentsMortarContactCondition<3,3, false, 3>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 27; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 3, 3>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 3, 3>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 3, 3>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 3, 3>& X2 = rDerivativeData.X2;

    const BoundedMatrix<double, 3, 3> LM = MortarUtilities::GetVariableMatrix<3, 3>(r_geometry, VECTOR_LAGRANGE_MULTIPLIER, 0);

    const BoundedMatrix<double, 3, 3>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 3> DynamicFactor = MortarUtilities::GetVariableVector<3>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 3>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 3, 3>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 3, 3>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[0];

        rLocalRHS[18]+=-LM(0,0)*crhs0;
        rLocalRHS[19]+=-LM(0,1)*crhs0;
        rLocalRHS[20]+=-LM(0,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(0,0)*(DOperator(0,0)*(X1(0,0) + u1(0,0)) + DOperator(0,1)*(X1(1,0) + u1(1,0)) + DOperator(0,2)*(X1(2,0) + u1(2,0)) - MOperator(0,0)*(X2(0,0) + u2(0,0)) - MOperator(0,1)*(X2(1,0) + u2(1,0)) - MOperator(0,2)*(X2(2,0) + u2(2,0))) + NormalSlave(0,1)*(DOperator(0,0)*(X1(0,1) + u1(0,1)) + DOperator(0,1)*(X1(1,1) + u1(1,1)) + DOperator(0,2)*(X1(2,1) + u1(2,1)) - MOperator(0,0)*(X2(0,1) + u2(0,1)) - MOperator(0,1)*(X2(1,1) + u2(1,1)) - MOperator(0,2)*(X2(2,1) + u2(2,1))) + NormalSlave(0,2)*(DOperator(0,0)*(X1(0,2) + u1(0,2)) + DOperator(0,1)*(X1(1,2) + u1(1,2)) + DOperator(0,2)*(X1(2,2) + u1(2,2)) - MOperator(0,0)*(X2(0,2) + u2(0,2)) - MOperator(0,1)*(X2(1,2) + u2(1,2)) - MOperator(0,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(0,0)*crhs0;
        const double crhs2 =     LM(0,0)*ScaleFactor - PenaltyParameter[0]*crhs1;
        const double crhs3 =     DynamicFactor[0]*MOperator(0,0);
        const double crhs4 =     NormalSlave(0,1)*crhs0;
        const double crhs5 =     LM(0,1)*ScaleFactor - PenaltyParameter[0]*crhs4;
        const double crhs6 =     NormalSlave(0,2)*crhs0;
        const double crhs7 =     LM(0,2)*ScaleFactor - PenaltyParameter[0]*crhs6;
        const double crhs8 =     DynamicFactor[0]*MOperator(0,1);
        const double crhs9 =     DynamicFactor[0]*MOperator(0,2);
        const double crhs10 =     DOperator(0,0)*DynamicFactor[0];
        const double crhs11 =     DOperator(0,1)*DynamicFactor[0];
        const double crhs12 =     DOperator(0,2)*DynamicFactor[0];
        const double crhs13 =     1.0/PenaltyParameter[0];
        const double crhs14 =     LM(0,0)*NormalSlave(0,0) + LM(0,1)*NormalSlave(0,1) + LM(0,2)*NormalSlave(0,2);
        const double crhs15 =     LM(0,1) - NormalSlave(0,1)*crhs14;
        const double crhs16 =     NormalSlave(0,0)*NormalSlave(0,1);
        const double crhs17 =     LM(0,2) - NormalSlave(0,2)*crhs14;
        const double crhs18 =     NormalSlave(0,2)*crhs17;
        const double crhs19 =     LM(0,0) - NormalSlave(0,0)*crhs14;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(0,0)*crhs18 + crhs15*crhs16 - crhs19*(1 - std::pow(NormalSlave(0,0), 2))) - crhs1);
        rLocalRHS[19]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(0,1)*crhs18 - crhs15*(1 - std::pow(NormalSlave(0,1), 2)) + crhs16*crhs19) - crhs4);
        rLocalRHS[20]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(0,0)*NormalSlave(0,2)*crhs19 + NormalSlave(0,1)*NormalSlave(0,2)*crhs15 - crhs17*(1 - std::pow(NormalSlave(0,2), 2))) - crhs6);
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[1];

        rLocalRHS[21]+=-LM(1,0)*crhs0;
        rLocalRHS[22]+=-LM(1,1)*crhs0;
        rLocalRHS[23]+=-LM(1,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(1,0)*(DOperator(1,0)*(X1(0,0) + u1(0,0)) + DOperator(1,1)*(X1(1,0) + u1(1,0)) + DOperator(1,2)*(X1(2,0) + u1(2,0)) - MOperator(1,0)*(X2(0,0) + u2(0,0)) - MOperator(1,1)*(X2(1,0) + u2(1,0)) - MOperator(1,2)*(X2(2,0) + u2(2,0))) + NormalSlave(1,1)*(DOperator(1,0)*(X1(0,1) + u1(0,1)) + DOperator(1,1)*(X1(1,1) + u1(1,1)) + DOperator(1,2)*(X1(2,1) + u1(2,1)) - MOperator(1,0)*(X2(0,1) + u2(0,1)) - MOperator(1,1)*(X2(1,1) + u2(1,1)) - MOperator(1,2)*(X2(2,1) + u2(2,1))) + NormalSlave(1,2)*(DOperator(1,0)*(X1(0,2) + u1(0,2)) + DOperator(1,1)*(X1(1,2) + u1(1,2)) + DOperator(1,2)*(X1(2,2) + u1(2,2)) - MOperator(1,0)*(X2(0,2) + u2(0,2)) - MOperator(1,1)*(X2(1,2) + u2(1,2)) - MOperator(1,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(1,0)*crhs0;
        const double crhs2 =     LM(1,0)*ScaleFactor - PenaltyParameter[1]*crhs1;
        const double crhs3 =     DynamicFactor[1]*MOperator(1,0);
        const double crhs4 =     NormalSlave(1,1)*crhs0;
        const double crhs5 =     LM(1,1)*ScaleFactor - PenaltyParameter[1]*crhs4;
        const double crhs6 =     NormalSlave(1,2)*crhs0;
        const double crhs7 =     LM(1,2)*ScaleFactor - PenaltyParameter[1]*crhs6;
        const double crhs8 =     DynamicFactor[1]*MOperator(1,1);
        const double crhs9 =     DynamicFactor[1]*MOperator(1,2);
        const double crhs10 =     DOperator(1,0)*DynamicFactor[1];
        const double crhs11 =     DOperator(1,1)*DynamicFactor[1];
        const double crhs12 =     DOperator(1,2)*DynamicFactor[1];
        const double crhs13 =     1.0/PenaltyParameter[1];
        const double crhs14 =     LM(1,0)*NormalSlave(1,0) + LM(1,1)*NormalSlave(1,1) + LM(1,2)*NormalSlave(1,2);
        const double crhs15 =     LM(1,1) - NormalSlave(1,1)*crhs14;
        const double crhs16 =     NormalSlave(1,0)*NormalSlave(1,1);
        const double crhs17 =     LM(1,2) - NormalSlave(1,2)*crhs14;
        const double crhs18 =     NormalSlave(1,2)*crhs17;
        const double crhs19 =     LM(1,0) - NormalSlave(1,0)*crhs14;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[21]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(1,0)*crhs18 + crhs15*crhs16 - crhs19*(1 - std::pow(NormalSlave(1,0), 2))) - crhs1);
        rLocalRHS[22]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(1,1)*crhs18 - crhs15*(1 - std::pow(NormalSlave(1,1), 2)) + crhs16*crhs19) - crhs4);
        rLocalRHS[23]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(1,0)*NormalSlave(1,2)*crhs19 + NormalSlave(1,1)*NormalSlave(1,2)*crhs15 - crhs17*(1 - std::pow(NormalSlave(1,2), 2))) - crhs6);
    }

    // NODE 2
    if (r_geometry[2].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[2];

        rLocalRHS[24]+=-LM(2,0)*crhs0;
        rLocalRHS[25]+=-LM(2,1)*crhs0;
        rLocalRHS[26]+=-LM(2,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(2,0)*(DOperator(2,0)*(X1(0,0) + u1(0,0)) + DOperator(2,1)*(X1(1,0) + u1(1,0)) + DOperator(2,2)*(X1(2,0) + u1(2,0)) - MOperator(2,0)*(X2(0,0) + u2(0,0)) - MOperator(2,1)*(X2(1,0) + u2(1,0)) - MOperator(2,2)*(X2(2,0) + u2(2,0))) + NormalSlave(2,1)*(DOperator(2,0)*(X1(0,1) + u1(0,1)) + DOperator(2,1)*(X1(1,1) + u1(1,1)) + DOperator(2,2)*(X1(2,1) + u1(2,1)) - MOperator(2,0)*(X2(0,1) + u2(0,1)) - MOperator(2,1)*(X2(1,1) + u2(1,1)) - MOperator(2,2)*(X2(2,1) + u2(2,1))) + NormalSlave(2,2)*(DOperator(2,0)*(X1(0,2) + u1(0,2)) + DOperator(2,1)*(X1(1,2) + u1(1,2)) + DOperator(2,2)*(X1(2,2) + u1(2,2)) - MOperator(2,0)*(X2(0,2) + u2(0,2)) - MOperator(2,1)*(X2(1,2) + u2(1,2)) - MOperator(2,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(2,0)*crhs0;
        const double crhs2 =     LM(2,0)*ScaleFactor - PenaltyParameter[2]*crhs1;
        const double crhs3 =     DynamicFactor[2]*MOperator(2,0);
        const double crhs4 =     NormalSlave(2,1)*crhs0;
        const double crhs5 =     LM(2,1)*ScaleFactor - PenaltyParameter[2]*crhs4;
        const double crhs6 =     NormalSlave(2,2)*crhs0;
        const double crhs7 =     LM(2,2)*ScaleFactor - PenaltyParameter[2]*crhs6;
        const double crhs8 =     DynamicFactor[2]*MOperator(2,1);
        const double crhs9 =     DynamicFactor[2]*MOperator(2,2);
        const double crhs10 =     DOperator(2,0)*DynamicFactor[2];
        const double crhs11 =     DOperator(2,1)*DynamicFactor[2];
        const double crhs12 =     DOperator(2,2)*DynamicFactor[2];
        const double crhs13 =     1.0/PenaltyParameter[2];
        const double crhs14 =     LM(2,0)*NormalSlave(2,0) + LM(2,1)*NormalSlave(2,1) + LM(2,2)*NormalSlave(2,2);
        const double crhs15 =     LM(2,1) - NormalSlave(2,1)*crhs14;
        const double crhs16 =     NormalSlave(2,0)*NormalSlave(2,1);
        const double crhs17 =     LM(2,2) - NormalSlave(2,2)*crhs14;
        const double crhs18 =     NormalSlave(2,2)*crhs17;
        const double crhs19 =     LM(2,0) - NormalSlave(2,0)*crhs14;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[24]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(2,0)*crhs18 + crhs15*crhs16 - crhs19*(1 - std::pow(NormalSlave(2,0), 2))) - crhs1);
        rLocalRHS[25]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(2,1)*crhs18 - crhs15*(1 - std::pow(NormalSlave(2,1), 2)) + crhs16*crhs19) - crhs4);
        rLocalRHS[26]+=ScaleFactor*(ScaleFactor*crhs13*(NormalSlave(2,0)*NormalSlave(2,2)*crhs19 + NormalSlave(2,1)*NormalSlave(2,2)*crhs15 - crhs17*(1 - std::pow(NormalSlave(2,2), 2))) - crhs6);
    }
}

/***********************************************************************************/
/***********************************************************************************/

template<>
void AugmentedLagrangianMethodFrictionlessComponentsMortarContactCondition<3,4, false, 4>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 36; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 4, 3>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 4, 3>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 4, 3>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 4, 3>& X2 = rDerivativeData.X2;

    const BoundedMatrix<double, 4, 3> LM = MortarUtilities::GetVariableMatrix<3, 4>(r_geometry, VECTOR_LAGRANGE_MULTIPLIER, 0);

    const BoundedMatrix<double, 4, 3>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 4> DynamicFactor = MortarUtilities::GetVariableVector<4>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 4>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 4, 4>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 4, 4>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[0];

        rLocalRHS[24]+=-LM(0,0)*crhs0;
        rLocalRHS[25]+=-LM(0,1)*crhs0;
        rLocalRHS[26]+=-LM(0,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(0,0)*(DOperator(0,0)*(X1(0,0) + u1(0,0)) + DOperator(0,1)*(X1(1,0) + u1(1,0)) + DOperator(0,2)*(X1(2,0) + u1(2,0)) + DOperator(0,3)*(X1(3,0) + u1(3,0)) - MOperator(0,0)*(X2(0,0) + u2(0,0)) - MOperator(0,1)*(X2(1,0) + u2(1,0)) - MOperator(0,2)*(X2(2,0) + u2(2,0)) - MOperator(0,3)*(X2(3,0) + u2(3,0))) + NormalSlave(0,1)*(DOperator(0,0)*(X1(0,1) + u1(0,1)) + DOperator(0,1)*(X1(1,1) + u1(1,1)) + DOperator(0,2)*(X1(2,1) + u1(2,1)) + DOperator(0,3)*(X1(3,1) + u1(3,1)) - MOperator(0,0)*(X2(0,1) + u2(0,1)) - MOperator(0,1)*(X2(1,1) + u2(1,1)) - MOperator(0,2)*(X2(2,1) + u2(2,1)) - MOperator(0,3)*(X2(3,1) + u2(3,1))) + NormalSlave(0,2)*(DOperator(0,0)*(X1(0,2) + u1(0,2)) + DOperator(0,1)*(X1(1,2) + u1(1,2)) + DOperator(0,2)*(X1(2,2) + u1(2,2)) + DOperator(0,3)*(X1(3,2) + u1(3,2)) - MOperator(0,0)*(X2(0,2) + u2(0,2)) - MOperator(0,1)*(X2(1,2) + u2(1,2)) - MOperator(0,2)*(X2(2,2) + u2(2,2)) - MOperator(0,3)*(X2(3,2) + u2(3,2)));
        const double crhs1 =     NormalSlave(0,0)*crhs0;
        const double crhs2 =     LM(0,0)*ScaleFactor - PenaltyParameter[0]*crhs1;
        const double crhs3 =     DynamicFactor[0]*MOperator(0,0);
        const double crhs4 =     NormalSlave(0,1)*crhs0;
        const double crhs5 =     LM(0,1)*ScaleFactor - PenaltyParameter[0]*crhs4;
        const double crhs6 =     NormalSlave(0,2)*crhs0;
        const double crhs7 =     LM(0,2)*ScaleFactor - PenaltyParameter[0]*crhs6;
        const double crhs8 =     DynamicFactor[0]*MOperator(0,1);
        const double crhs9 =     DynamicFactor[0]*MOperator(0,2);
        const double crhs10 =     DynamicFactor[0]*MOperator(0,3);
        const double crhs11 =     DOperator(0,0)*DynamicFactor[0];
        const double crhs12 =     DOperator(0,1)*DynamicFactor[0];
        const double crhs13 =     DOperator(0,2)*DynamicFactor[0];
        const double crhs14 =     DOperator(0,3)*DynamicFactor[0];
        const double crhs15 =     1.0/PenaltyParameter[0];
        const double crhs16 =     LM(0,0)*NormalSlave(0,0) + LM(0,1)*NormalSlave(0,1) + LM(0,2)*NormalSlave(0,2);
        const double crhs17 =     LM(0,1) - NormalSlave(0,1)*crhs16;
        const double crhs18 =     NormalSlave(0,0)*NormalSlave(0,1);
        const double crhs19 =     LM(0,2) - NormalSlave(0,2)*crhs16;
        const double crhs20 =     NormalSlave(0,2)*crhs19;
        const double crhs21 =     LM(0,0) - NormalSlave(0,0)*crhs16;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs2;
        rLocalRHS[10]+=-crhs10*crhs5;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[21]+=crhs14*crhs2;
        rLocalRHS[22]+=crhs14*crhs5;
        rLocalRHS[23]+=crhs14*crhs7;
        rLocalRHS[24]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(0,0)*crhs20 + crhs17*crhs18 - crhs21*(1 - std::pow(NormalSlave(0,0), 2))) - crhs1);
        rLocalRHS[25]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(0,1)*crhs20 - crhs17*(1 - std::pow(NormalSlave(0,1), 2)) + crhs18*crhs21) - crhs4);
        rLocalRHS[26]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(0,0)*NormalSlave(0,2)*crhs21 + NormalSlave(0,1)*NormalSlave(0,2)*crhs17 - crhs19*(1 - std::pow(NormalSlave(0,2), 2))) - crhs6);
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[1];

        rLocalRHS[27]+=-LM(1,0)*crhs0;
        rLocalRHS[28]+=-LM(1,1)*crhs0;
        rLocalRHS[29]+=-LM(1,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(1,0)*(DOperator(1,0)*(X1(0,0) + u1(0,0)) + DOperator(1,1)*(X1(1,0) + u1(1,0)) + DOperator(1,2)*(X1(2,0) + u1(2,0)) + DOperator(1,3)*(X1(3,0) + u1(3,0)) - MOperator(1,0)*(X2(0,0) + u2(0,0)) - MOperator(1,1)*(X2(1,0) + u2(1,0)) - MOperator(1,2)*(X2(2,0) + u2(2,0)) - MOperator(1,3)*(X2(3,0) + u2(3,0))) + NormalSlave(1,1)*(DOperator(1,0)*(X1(0,1) + u1(0,1)) + DOperator(1,1)*(X1(1,1) + u1(1,1)) + DOperator(1,2)*(X1(2,1) + u1(2,1)) + DOperator(1,3)*(X1(3,1) + u1(3,1)) - MOperator(1,0)*(X2(0,1) + u2(0,1)) - MOperator(1,1)*(X2(1,1) + u2(1,1)) - MOperator(1,2)*(X2(2,1) + u2(2,1)) - MOperator(1,3)*(X2(3,1) + u2(3,1))) + NormalSlave(1,2)*(DOperator(1,0)*(X1(0,2) + u1(0,2)) + DOperator(1,1)*(X1(1,2) + u1(1,2)) + DOperator(1,2)*(X1(2,2) + u1(2,2)) + DOperator(1,3)*(X1(3,2) + u1(3,2)) - MOperator(1,0)*(X2(0,2) + u2(0,2)) - MOperator(1,1)*(X2(1,2) + u2(1,2)) - MOperator(1,2)*(X2(2,2) + u2(2,2)) - MOperator(1,3)*(X2(3,2) + u2(3,2)));
        const double crhs1 =     NormalSlave(1,0)*crhs0;
        const double crhs2 =     LM(1,0)*ScaleFactor - PenaltyParameter[1]*crhs1;
        const double crhs3 =     DynamicFactor[1]*MOperator(1,0);
        const double crhs4 =     NormalSlave(1,1)*crhs0;
        const double crhs5 =     LM(1,1)*ScaleFactor - PenaltyParameter[1]*crhs4;
        const double crhs6 =     NormalSlave(1,2)*crhs0;
        const double crhs7 =     LM(1,2)*ScaleFactor - PenaltyParameter[1]*crhs6;
        const double crhs8 =     DynamicFactor[1]*MOperator(1,1);
        const double crhs9 =     DynamicFactor[1]*MOperator(1,2);
        const double crhs10 =     DynamicFactor[1]*MOperator(1,3);
        const double crhs11 =     DOperator(1,0)*DynamicFactor[1];
        const double crhs12 =     DOperator(1,1)*DynamicFactor[1];
        const double crhs13 =     DOperator(1,2)*DynamicFactor[1];
        const double crhs14 =     DOperator(1,3)*DynamicFactor[1];
        const double crhs15 =     1.0/PenaltyParameter[1];
        const double crhs16 =     LM(1,0)*NormalSlave(1,0) + LM(1,1)*NormalSlave(1,1) + LM(1,2)*NormalSlave(1,2);
        const double crhs17 =     LM(1,1) - NormalSlave(1,1)*crhs16;
        const double crhs18 =     NormalSlave(1,0)*NormalSlave(1,1);
        const double crhs19 =     LM(1,2) - NormalSlave(1,2)*crhs16;
        const double crhs20 =     NormalSlave(1,2)*crhs19;
        const double crhs21 =     LM(1,0) - NormalSlave(1,0)*crhs16;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs2;
        rLocalRHS[10]+=-crhs10*crhs5;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[21]+=crhs14*crhs2;
        rLocalRHS[22]+=crhs14*crhs5;
        rLocalRHS[23]+=crhs14*crhs7;
        rLocalRHS[27]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(1,0)*crhs20 + crhs17*crhs18 - crhs21*(1 - std::pow(NormalSlave(1,0), 2))) - crhs1);
        rLocalRHS[28]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(1,1)*crhs20 - crhs17*(1 - std::pow(NormalSlave(1,1), 2)) + crhs18*crhs21) - crhs4);
        rLocalRHS[29]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(1,0)*NormalSlave(1,2)*crhs21 + NormalSlave(1,1)*NormalSlave(1,2)*crhs17 - crhs19*(1 - std::pow(NormalSlave(1,2), 2))) - crhs6);
    }

    // NODE 2
    if (r_geometry[2].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[2];

        rLocalRHS[30]+=-LM(2,0)*crhs0;
        rLocalRHS[31]+=-LM(2,1)*crhs0;
        rLocalRHS[32]+=-LM(2,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(2,0)*(DOperator(2,0)*(X1(0,0) + u1(0,0)) + DOperator(2,1)*(X1(1,0) + u1(1,0)) + DOperator(2,2)*(X1(2,0) + u1(2,0)) + DOperator(2,3)*(X1(3,0) + u1(3,0)) - MOperator(2,0)*(X2(0,0) + u2(0,0)) - MOperator(2,1)*(X2(1,0) + u2(1,0)) - MOperator(2,2)*(X2(2,0) + u2(2,0)) - MOperator(2,3)*(X2(3,0) + u2(3,0))) + NormalSlave(2,1)*(DOperator(2,0)*(X1(0,1) + u1(0,1)) + DOperator(2,1)*(X1(1,1) + u1(1,1)) + DOperator(2,2)*(X1(2,1) + u1(2,1)) + DOperator(2,3)*(X1(3,1) + u1(3,1)) - MOperator(2,0)*(X2(0,1) + u2(0,1)) - MOperator(2,1)*(X2(1,1) + u2(1,1)) - MOperator(2,2)*(X2(2,1) + u2(2,1)) - MOperator(2,3)*(X2(3,1) + u2(3,1))) + NormalSlave(2,2)*(DOperator(2,0)*(X1(0,2) + u1(0,2)) + DOperator(2,1)*(X1(1,2) + u1(1,2)) + DOperator(2,2)*(X1(2,2) + u1(2,2)) + DOperator(2,3)*(X1(3,2) + u1(3,2)) - MOperator(2,0)*(X2(0,2) + u2(0,2)) - MOperator(2,1)*(X2(1,2) + u2(1,2)) - MOperator(2,2)*(X2(2,2) + u2(2,2)) - MOperator(2,3)*(X2(3,2) + u2(3,2)));
        const double crhs1 =     NormalSlave(2,0)*crhs0;
        const double crhs2 =     LM(2,0)*ScaleFactor - PenaltyParameter[2]*crhs1;
        const double crhs3 =     DynamicFactor[2]*MOperator(2,0);
        const double crhs4 =     NormalSlave(2,1)*crhs0;
        const double crhs5 =     LM(2,1)*ScaleFactor - PenaltyParameter[2]*crhs4;
        const double crhs6 =     NormalSlave(2,2)*crhs0;
        const double crhs7 =     LM(2,2)*ScaleFactor - PenaltyParameter[2]*crhs6;
        const double crhs8 =     DynamicFactor[2]*MOperator(2,1);
        const double crhs9 =     DynamicFactor[2]*MOperator(2,2);
        const double crhs10 =     DynamicFactor[2]*MOperator(2,3);
        const double crhs11 =     DOperator(2,0)*DynamicFactor[2];
        const double crhs12 =     DOperator(2,1)*DynamicFactor[2];
        const double crhs13 =     DOperator(2,2)*DynamicFactor[2];
        const double crhs14 =     DOperator(2,3)*DynamicFactor[2];
        const double crhs15 =     1.0/PenaltyParameter[2];
        const double crhs16 =     LM(2,0)*NormalSlave(2,0) + LM(2,1)*NormalSlave(2,1) + LM(2,2)*NormalSlave(2,2);
        const double crhs17 =     LM(2,1) - NormalSlave(2,1)*crhs16;
        const double crhs18 =     NormalSlave(2,0)*NormalSlave(2,1);
        const double crhs19 =     LM(2,2) - NormalSlave(2,2)*crhs16;
        const double crhs20 =     NormalSlave(2,2)*crhs19;
        const double crhs21 =     LM(2,0) - NormalSlave(2,0)*crhs16;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs2;
        rLocalRHS[10]+=-crhs10*crhs5;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[21]+=crhs14*crhs2;
        rLocalRHS[22]+=crhs14*crhs5;
        rLocalRHS[23]+=crhs14*crhs7;
        rLocalRHS[30]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(2,0)*crhs20 + crhs17*crhs18 - crhs21*(1 - std::pow(NormalSlave(2,0), 2))) - crhs1);
        rLocalRHS[31]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(2,1)*crhs20 - crhs17*(1 - std::pow(NormalSlave(2,1), 2)) + crhs18*crhs21) - crhs4);
        rLocalRHS[32]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(2,0)*NormalSlave(2,2)*crhs21 + NormalSlave(2,1)*NormalSlave(2,2)*crhs17 - crhs19*(1 - std::pow(NormalSlave(2,2), 2))) - crhs6);
    }

    // NODE 3
    if (r_geometry[3].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[3];

        rLocalRHS[33]+=-LM(3,0)*crhs0;
        rLocalRHS[34]+=-LM(3,1)*crhs0;
        rLocalRHS[35]+=-LM(3,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(3,0)*(DOperator(3,0)*(X1(0,0) + u1(0,0)) + DOperator(3,1)*(X1(1,0) + u1(1,0)) + DOperator(3,2)*(X1(2,0) + u1(2,0)) + DOperator(3,3)*(X1(3,0) + u1(3,0)) - MOperator(3,0)*(X2(0,0) + u2(0,0)) - MOperator(3,1)*(X2(1,0) + u2(1,0)) - MOperator(3,2)*(X2(2,0) + u2(2,0)) - MOperator(3,3)*(X2(3,0) + u2(3,0))) + NormalSlave(3,1)*(DOperator(3,0)*(X1(0,1) + u1(0,1)) + DOperator(3,1)*(X1(1,1) + u1(1,1)) + DOperator(3,2)*(X1(2,1) + u1(2,1)) + DOperator(3,3)*(X1(3,1) + u1(3,1)) - MOperator(3,0)*(X2(0,1) + u2(0,1)) - MOperator(3,1)*(X2(1,1) + u2(1,1)) - MOperator(3,2)*(X2(2,1) + u2(2,1)) - MOperator(3,3)*(X2(3,1) + u2(3,1))) + NormalSlave(3,2)*(DOperator(3,0)*(X1(0,2) + u1(0,2)) + DOperator(3,1)*(X1(1,2) + u1(1,2)) + DOperator(3,2)*(X1(2,2) + u1(2,2)) + DOperator(3,3)*(X1(3,2) + u1(3,2)) - MOperator(3,0)*(X2(0,2) + u2(0,2)) - MOperator(3,1)*(X2(1,2) + u2(1,2)) - MOperator(3,2)*(X2(2,2) + u2(2,2)) - MOperator(3,3)*(X2(3,2) + u2(3,2)));
        const double crhs1 =     NormalSlave(3,0)*crhs0;
        const double crhs2 =     LM(3,0)*ScaleFactor - PenaltyParameter[3]*crhs1;
        const double crhs3 =     DynamicFactor[3]*MOperator(3,0);
        const double crhs4 =     NormalSlave(3,1)*crhs0;
        const double crhs5 =     LM(3,1)*ScaleFactor - PenaltyParameter[3]*crhs4;
        const double crhs6 =     NormalSlave(3,2)*crhs0;
        const double crhs7 =     LM(3,2)*ScaleFactor - PenaltyParameter[3]*crhs6;
        const double crhs8 =     DynamicFactor[3]*MOperator(3,1);
        const double crhs9 =     DynamicFactor[3]*MOperator(3,2);
        const double crhs10 =     DynamicFactor[3]*MOperator(3,3);
        const double crhs11 =     DOperator(3,0)*DynamicFactor[3];
        const double crhs12 =     DOperator(3,1)*DynamicFactor[3];
        const double crhs13 =     DOperator(3,2)*DynamicFactor[3];
        const double crhs14 =     DOperator(3,3)*DynamicFactor[3];
        const double crhs15 =     1.0/PenaltyParameter[3];
        const double crhs16 =     LM(3,0)*NormalSlave(3,0) + LM(3,1)*NormalSlave(3,1) + LM(3,2)*NormalSlave(3,2);
        const double crhs17 =     LM(3,1) - NormalSlave(3,1)*crhs16;
        const double crhs18 =     NormalSlave(3,0)*NormalSlave(3,1);
        const double crhs19 =     LM(3,2) - NormalSlave(3,2)*crhs16;
        const double crhs20 =     NormalSlave(3,2)*crhs19;
        const double crhs21 =     LM(3,0) - NormalSlave(3,0)*crhs16;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs2;
        rLocalRHS[10]+=-crhs10*crhs5;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[21]+=crhs14*crhs2;
        rLocalRHS[22]+=crhs14*crhs5;
        rLocalRHS[23]+=crhs14*crhs7;
        rLocalRHS[33]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(3,0)*crhs20 + crhs17*crhs18 - crhs21*(1 - std::pow(NormalSlave(3,0), 2))) - crhs1);
        rLocalRHS[34]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(3,1)*crhs20 - crhs17*(1 - std::pow(NormalSlave(3,1), 2)) + crhs18*crhs21) - crhs4);
        rLocalRHS[35]+=ScaleFactor*(ScaleFactor*crhs15*(NormalSlave(3,0)*NormalSlave(3,2)*crhs21 + NormalSlave(3,1)*NormalSlave(3,2)*crhs17 - crhs19*(1 - std::pow(NormalSlave(3,2), 2))) - crhs6);
    }
}

/***********************************************************************************/
/***********************************************************************************/

template<>
void AugmentedLagrangianMethodFrictionlessComponentsMortarContactCondition<3,3, false, 4>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 30; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 3, 3>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 4, 3>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 3, 3>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 4, 3>& X2 = rDerivativeData.X2;

    const BoundedMatrix<double, 3, 3> LM = MortarUtilities::GetVariableMatrix<3, 3>(r_geometry, VECTOR_LAGRANGE_MULTIPLIER, 0);

    const BoundedMatrix<double, 3, 3>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 3> DynamicFactor = MortarUtilities::GetVariableVector<3>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 3>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 3, 4>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 3, 3>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[0];

        rLocalRHS[21]+=-LM(0,0)*crhs0;
        rLocalRHS[22]+=-LM(0,1)*crhs0;
        rLocalRHS[23]+=-LM(0,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     -DOperator(0,0)*(X1(0,0) + u1(0,0)) - DOperator(0,1)*(X1(1,0) + u1(1,0)) - DOperator(0,2)*(X1(2,0) + u1(2,0)) + MOperator(0,0)*(X2(0,0) + u2(0,0)) + MOperator(0,1)*(X2(1,0) + u2(1,0)) + MOperator(0,2)*(X2(2,0) + u2(2,0)) + MOperator(0,3)*(X2(3,0) + u2(3,0));
        const double crhs1 =     -DOperator(0,0)*(X1(0,1) + u1(0,1)) - DOperator(0,1)*(X1(1,1) + u1(1,1)) - DOperator(0,2)*(X1(2,1) + u1(2,1)) + MOperator(0,0)*(X2(0,1) + u2(0,1)) + MOperator(0,1)*(X2(1,1) + u2(1,1)) + MOperator(0,2)*(X2(2,1) + u2(2,1)) + MOperator(0,3)*(X2(3,1) + u2(3,1));
        const double crhs2 =     -DOperator(0,0)*(X1(0,2) + u1(0,2)) - DOperator(0,1)*(X1(1,2) + u1(1,2)) - DOperator(0,2)*(X1(2,2) + u1(2,2)) + MOperator(0,0)*(X2(0,2) + u2(0,2)) + MOperator(0,1)*(X2(1,2) + u2(1,2)) + MOperator(0,2)*(X2(2,2) + u2(2,2)) + MOperator(0,3)*(X2(3,2) + u2(3,2));
        const double crhs3 =     PenaltyParameter[0]*(NormalSlave(0,0)*crhs0 + NormalSlave(0,1)*crhs1 + NormalSlave(0,2)*crhs2);
        const double crhs4 =     LM(0,0)*ScaleFactor + NormalSlave(0,0)*crhs3;
        const double crhs5 =     DynamicFactor[0]*MOperator(0,0);
        const double crhs6 =     LM(0,1)*ScaleFactor + NormalSlave(0,1)*crhs3;
        const double crhs7 =     LM(0,2)*ScaleFactor + NormalSlave(0,2)*crhs3;
        const double crhs8 =     DynamicFactor[0]*MOperator(0,1);
        const double crhs9 =     DynamicFactor[0]*MOperator(0,2);
        const double crhs10 =     DynamicFactor[0]*MOperator(0,3);
        const double crhs11 =     DOperator(0,0)*DynamicFactor[0];
        const double crhs12 =     DOperator(0,1)*DynamicFactor[0];
        const double crhs13 =     DOperator(0,2)*DynamicFactor[0];
        const double crhs14 =     1.0/PenaltyParameter[0];
        const double crhs15 =     LM(0,0)*NormalSlave(0,0) + LM(0,1)*NormalSlave(0,1) + LM(0,2)*NormalSlave(0,2);
        const double crhs16 =     LM(0,1) - NormalSlave(0,1)*crhs15;
        const double crhs17 =     NormalSlave(0,0)*NormalSlave(0,1);
        const double crhs18 =     LM(0,2) - NormalSlave(0,2)*crhs15;
        const double crhs19 =     NormalSlave(0,2)*crhs18;
        const double crhs20 =     LM(0,0) - NormalSlave(0,0)*crhs15;
        const double crhs21 =     -NormalSlave(0,0)*crhs0 - NormalSlave(0,1)*crhs1 - NormalSlave(0,2)*crhs2;

        rLocalRHS[0]+=-crhs4*crhs5;
        rLocalRHS[1]+=-crhs5*crhs6;
        rLocalRHS[2]+=-crhs5*crhs7;
        rLocalRHS[3]+=-crhs4*crhs8;
        rLocalRHS[4]+=-crhs6*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs4*crhs9;
        rLocalRHS[7]+=-crhs6*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs4;
        rLocalRHS[10]+=-crhs10*crhs6;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs4;
        rLocalRHS[13]+=crhs11*crhs6;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs4;
        rLocalRHS[16]+=crhs12*crhs6;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs4;
        rLocalRHS[19]+=crhs13*crhs6;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[21]+=ScaleFactor*(-NormalSlave(0,0)*crhs21 + ScaleFactor*crhs14*(NormalSlave(0,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(0,0), 2))));
        rLocalRHS[22]+=ScaleFactor*(-NormalSlave(0,1)*crhs21 + ScaleFactor*crhs14*(NormalSlave(0,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(0,1), 2)) + crhs17*crhs20));
        rLocalRHS[23]+=ScaleFactor*(-NormalSlave(0,2)*crhs21 + ScaleFactor*crhs14*(NormalSlave(0,0)*NormalSlave(0,2)*crhs20 + NormalSlave(0,1)*NormalSlave(0,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(0,2), 2))));
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[1];

        rLocalRHS[24]+=-LM(1,0)*crhs0;
        rLocalRHS[25]+=-LM(1,1)*crhs0;
        rLocalRHS[26]+=-LM(1,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     -DOperator(1,0)*(X1(0,0) + u1(0,0)) - DOperator(1,1)*(X1(1,0) + u1(1,0)) - DOperator(1,2)*(X1(2,0) + u1(2,0)) + MOperator(1,0)*(X2(0,0) + u2(0,0)) + MOperator(1,1)*(X2(1,0) + u2(1,0)) + MOperator(1,2)*(X2(2,0) + u2(2,0)) + MOperator(1,3)*(X2(3,0) + u2(3,0));
        const double crhs1 =     -DOperator(1,0)*(X1(0,1) + u1(0,1)) - DOperator(1,1)*(X1(1,1) + u1(1,1)) - DOperator(1,2)*(X1(2,1) + u1(2,1)) + MOperator(1,0)*(X2(0,1) + u2(0,1)) + MOperator(1,1)*(X2(1,1) + u2(1,1)) + MOperator(1,2)*(X2(2,1) + u2(2,1)) + MOperator(1,3)*(X2(3,1) + u2(3,1));
        const double crhs2 =     -DOperator(1,0)*(X1(0,2) + u1(0,2)) - DOperator(1,1)*(X1(1,2) + u1(1,2)) - DOperator(1,2)*(X1(2,2) + u1(2,2)) + MOperator(1,0)*(X2(0,2) + u2(0,2)) + MOperator(1,1)*(X2(1,2) + u2(1,2)) + MOperator(1,2)*(X2(2,2) + u2(2,2)) + MOperator(1,3)*(X2(3,2) + u2(3,2));
        const double crhs3 =     PenaltyParameter[1]*(NormalSlave(1,0)*crhs0 + NormalSlave(1,1)*crhs1 + NormalSlave(1,2)*crhs2);
        const double crhs4 =     LM(1,0)*ScaleFactor + NormalSlave(1,0)*crhs3;
        const double crhs5 =     DynamicFactor[1]*MOperator(1,0);
        const double crhs6 =     LM(1,1)*ScaleFactor + NormalSlave(1,1)*crhs3;
        const double crhs7 =     LM(1,2)*ScaleFactor + NormalSlave(1,2)*crhs3;
        const double crhs8 =     DynamicFactor[1]*MOperator(1,1);
        const double crhs9 =     DynamicFactor[1]*MOperator(1,2);
        const double crhs10 =     DynamicFactor[1]*MOperator(1,3);
        const double crhs11 =     DOperator(1,0)*DynamicFactor[1];
        const double crhs12 =     DOperator(1,1)*DynamicFactor[1];
        const double crhs13 =     DOperator(1,2)*DynamicFactor[1];
        const double crhs14 =     1.0/PenaltyParameter[1];
        const double crhs15 =     LM(1,0)*NormalSlave(1,0) + LM(1,1)*NormalSlave(1,1) + LM(1,2)*NormalSlave(1,2);
        const double crhs16 =     LM(1,1) - NormalSlave(1,1)*crhs15;
        const double crhs17 =     NormalSlave(1,0)*NormalSlave(1,1);
        const double crhs18 =     LM(1,2) - NormalSlave(1,2)*crhs15;
        const double crhs19 =     NormalSlave(1,2)*crhs18;
        const double crhs20 =     LM(1,0) - NormalSlave(1,0)*crhs15;
        const double crhs21 =     -NormalSlave(1,0)*crhs0 - NormalSlave(1,1)*crhs1 - NormalSlave(1,2)*crhs2;

        rLocalRHS[0]+=-crhs4*crhs5;
        rLocalRHS[1]+=-crhs5*crhs6;
        rLocalRHS[2]+=-crhs5*crhs7;
        rLocalRHS[3]+=-crhs4*crhs8;
        rLocalRHS[4]+=-crhs6*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs4*crhs9;
        rLocalRHS[7]+=-crhs6*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs4;
        rLocalRHS[10]+=-crhs10*crhs6;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs4;
        rLocalRHS[13]+=crhs11*crhs6;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs4;
        rLocalRHS[16]+=crhs12*crhs6;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs4;
        rLocalRHS[19]+=crhs13*crhs6;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[24]+=ScaleFactor*(-NormalSlave(1,0)*crhs21 + ScaleFactor*crhs14*(NormalSlave(1,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(1,0), 2))));
        rLocalRHS[25]+=ScaleFactor*(-NormalSlave(1,1)*crhs21 + ScaleFactor*crhs14*(NormalSlave(1,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(1,1), 2)) + crhs17*crhs20));
        rLocalRHS[26]+=ScaleFactor*(-NormalSlave(1,2)*crhs21 + ScaleFactor*crhs14*(NormalSlave(1,0)*NormalSlave(1,2)*crhs20 + NormalSlave(1,1)*NormalSlave(1,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(1,2), 2))));
    }

    // NODE 2
    if (r_geometry[2].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[2];

        rLocalRHS[27]+=-LM(2,0)*crhs0;
        rLocalRHS[28]+=-LM(2,1)*crhs0;
        rLocalRHS[29]+=-LM(2,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     -DOperator(2,0)*(X1(0,0) + u1(0,0)) - DOperator(2,1)*(X1(1,0) + u1(1,0)) - DOperator(2,2)*(X1(2,0) + u1(2,0)) + MOperator(2,0)*(X2(0,0) + u2(0,0)) + MOperator(2,1)*(X2(1,0) + u2(1,0)) + MOperator(2,2)*(X2(2,0) + u2(2,0)) + MOperator(2,3)*(X2(3,0) + u2(3,0));
        const double crhs1 =     -DOperator(2,0)*(X1(0,1) + u1(0,1)) - DOperator(2,1)*(X1(1,1) + u1(1,1)) - DOperator(2,2)*(X1(2,1) + u1(2,1)) + MOperator(2,0)*(X2(0,1) + u2(0,1)) + MOperator(2,1)*(X2(1,1) + u2(1,1)) + MOperator(2,2)*(X2(2,1) + u2(2,1)) + MOperator(2,3)*(X2(3,1) + u2(3,1));
        const double crhs2 =     -DOperator(2,0)*(X1(0,2) + u1(0,2)) - DOperator(2,1)*(X1(1,2) + u1(1,2)) - DOperator(2,2)*(X1(2,2) + u1(2,2)) + MOperator(2,0)*(X2(0,2) + u2(0,2)) + MOperator(2,1)*(X2(1,2) + u2(1,2)) + MOperator(2,2)*(X2(2,2) + u2(2,2)) + MOperator(2,3)*(X2(3,2) + u2(3,2));
        const double crhs3 =     PenaltyParameter[2]*(NormalSlave(2,0)*crhs0 + NormalSlave(2,1)*crhs1 + NormalSlave(2,2)*crhs2);
        const double crhs4 =     LM(2,0)*ScaleFactor + NormalSlave(2,0)*crhs3;
        const double crhs5 =     DynamicFactor[2]*MOperator(2,0);
        const double crhs6 =     LM(2,1)*ScaleFactor + NormalSlave(2,1)*crhs3;
        const double crhs7 =     LM(2,2)*ScaleFactor + NormalSlave(2,2)*crhs3;
        const double crhs8 =     DynamicFactor[2]*MOperator(2,1);
        const double crhs9 =     DynamicFactor[2]*MOperator(2,2);
        const double crhs10 =     DynamicFactor[2]*MOperator(2,3);
        const double crhs11 =     DOperator(2,0)*DynamicFactor[2];
        const double crhs12 =     DOperator(2,1)*DynamicFactor[2];
        const double crhs13 =     DOperator(2,2)*DynamicFactor[2];
        const double crhs14 =     1.0/PenaltyParameter[2];
        const double crhs15 =     LM(2,0)*NormalSlave(2,0) + LM(2,1)*NormalSlave(2,1) + LM(2,2)*NormalSlave(2,2);
        const double crhs16 =     LM(2,1) - NormalSlave(2,1)*crhs15;
        const double crhs17 =     NormalSlave(2,0)*NormalSlave(2,1);
        const double crhs18 =     LM(2,2) - NormalSlave(2,2)*crhs15;
        const double crhs19 =     NormalSlave(2,2)*crhs18;
        const double crhs20 =     LM(2,0) - NormalSlave(2,0)*crhs15;
        const double crhs21 =     -NormalSlave(2,0)*crhs0 - NormalSlave(2,1)*crhs1 - NormalSlave(2,2)*crhs2;

        rLocalRHS[0]+=-crhs4*crhs5;
        rLocalRHS[1]+=-crhs5*crhs6;
        rLocalRHS[2]+=-crhs5*crhs7;
        rLocalRHS[3]+=-crhs4*crhs8;
        rLocalRHS[4]+=-crhs6*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs4*crhs9;
        rLocalRHS[7]+=-crhs6*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=-crhs10*crhs4;
        rLocalRHS[10]+=-crhs10*crhs6;
        rLocalRHS[11]+=-crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs4;
        rLocalRHS[13]+=crhs11*crhs6;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs4;
        rLocalRHS[16]+=crhs12*crhs6;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs4;
        rLocalRHS[19]+=crhs13*crhs6;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[27]+=ScaleFactor*(-NormalSlave(2,0)*crhs21 + ScaleFactor*crhs14*(NormalSlave(2,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(2,0), 2))));
        rLocalRHS[28]+=ScaleFactor*(-NormalSlave(2,1)*crhs21 + ScaleFactor*crhs14*(NormalSlave(2,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(2,1), 2)) + crhs17*crhs20));
        rLocalRHS[29]+=ScaleFactor*(-NormalSlave(2,2)*crhs21 + ScaleFactor*crhs14*(NormalSlave(2,0)*NormalSlave(2,2)*crhs20 + NormalSlave(2,1)*NormalSlave(2,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(2,2), 2))));
    }
}

/***********************************************************************************/
/***********************************************************************************/

template<>
void AugmentedLagrangianMethodFrictionlessComponentsMortarContactCondition<3,4, false, 3>::StaticCalculateLocalRHS(
    PairedCondition* pCondition,
    Vector& rLocalRHS,
    const MortarConditionMatrices& rMortarConditionMatrices,
    const DerivativeDataType& rDerivativeData,
    const IndexType rActiveInactive,
    const ProcessInfo& rCurrentProcessInfo
    )
{
    // Initialize
    for (std::size_t i = 0; i < 33; ++i)
        rLocalRHS[i] = 0.0;

    // The geometry of the condition
    const GeometryType& r_geometry = pCondition->GetParentGeometry();

    // Initialize values
    const BoundedMatrix<double, 4, 3>& u1 = rDerivativeData.u1;
    const BoundedMatrix<double, 3, 3>& u2 = rDerivativeData.u2;
    const BoundedMatrix<double, 4, 3>& X1 = rDerivativeData.X1;
    const BoundedMatrix<double, 3, 3>& X2 = rDerivativeData.X2;

    const BoundedMatrix<double, 4, 3> LM = MortarUtilities::GetVariableMatrix<3, 4>(r_geometry, VECTOR_LAGRANGE_MULTIPLIER, 0);

    const BoundedMatrix<double, 4, 3>& NormalSlave = rDerivativeData.NormalSlave;

    // The ALM parameters
    const array_1d<double, 4> DynamicFactor = MortarUtilities::GetVariableVector<4>(r_geometry, DYNAMIC_FACTOR);
    const double ScaleFactor = rDerivativeData.ScaleFactor;
    const array_1d<double, 4>& PenaltyParameter = rDerivativeData.PenaltyParameter;

    // Mortar operators
    const BoundedMatrix<double, 4, 3>& MOperator = rMortarConditionMatrices.MOperator;
    const BoundedMatrix<double, 4, 4>& DOperator = rMortarConditionMatrices.DOperator;


    // NODE 0
    if (r_geometry[0].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[0];

        rLocalRHS[21]+=-LM(0,0)*crhs0;
        rLocalRHS[22]+=-LM(0,1)*crhs0;
        rLocalRHS[23]+=-LM(0,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(0,0)*(DOperator(0,0)*(X1(0,0) + u1(0,0)) + DOperator(0,1)*(X1(1,0) + u1(1,0)) + DOperator(0,2)*(X1(2,0) + u1(2,0)) + DOperator(0,3)*(X1(3,0) + u1(3,0)) - MOperator(0,0)*(X2(0,0) + u2(0,0)) - MOperator(0,1)*(X2(1,0) + u2(1,0)) - MOperator(0,2)*(X2(2,0) + u2(2,0))) + NormalSlave(0,1)*(DOperator(0,0)*(X1(0,1) + u1(0,1)) + DOperator(0,1)*(X1(1,1) + u1(1,1)) + DOperator(0,2)*(X1(2,1) + u1(2,1)) + DOperator(0,3)*(X1(3,1) + u1(3,1)) - MOperator(0,0)*(X2(0,1) + u2(0,1)) - MOperator(0,1)*(X2(1,1) + u2(1,1)) - MOperator(0,2)*(X2(2,1) + u2(2,1))) + NormalSlave(0,2)*(DOperator(0,0)*(X1(0,2) + u1(0,2)) + DOperator(0,1)*(X1(1,2) + u1(1,2)) + DOperator(0,2)*(X1(2,2) + u1(2,2)) + DOperator(0,3)*(X1(3,2) + u1(3,2)) - MOperator(0,0)*(X2(0,2) + u2(0,2)) - MOperator(0,1)*(X2(1,2) + u2(1,2)) - MOperator(0,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(0,0)*crhs0;
        const double crhs2 =     LM(0,0)*ScaleFactor - PenaltyParameter[0]*crhs1;
        const double crhs3 =     DynamicFactor[0]*MOperator(0,0);
        const double crhs4 =     NormalSlave(0,1)*crhs0;
        const double crhs5 =     LM(0,1)*ScaleFactor - PenaltyParameter[0]*crhs4;
        const double crhs6 =     NormalSlave(0,2)*crhs0;
        const double crhs7 =     LM(0,2)*ScaleFactor - PenaltyParameter[0]*crhs6;
        const double crhs8 =     DynamicFactor[0]*MOperator(0,1);
        const double crhs9 =     DynamicFactor[0]*MOperator(0,2);
        const double crhs10 =     DOperator(0,0)*DynamicFactor[0];
        const double crhs11 =     DOperator(0,1)*DynamicFactor[0];
        const double crhs12 =     DOperator(0,2)*DynamicFactor[0];
        const double crhs13 =     DOperator(0,3)*DynamicFactor[0];
        const double crhs14 =     1.0/PenaltyParameter[0];
        const double crhs15 =     LM(0,0)*NormalSlave(0,0) + LM(0,1)*NormalSlave(0,1) + LM(0,2)*NormalSlave(0,2);
        const double crhs16 =     LM(0,1) - NormalSlave(0,1)*crhs15;
        const double crhs17 =     NormalSlave(0,0)*NormalSlave(0,1);
        const double crhs18 =     LM(0,2) - NormalSlave(0,2)*crhs15;
        const double crhs19 =     NormalSlave(0,2)*crhs18;
        const double crhs20 =     LM(0,0) - NormalSlave(0,0)*crhs15;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[21]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(0,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(0,0), 2))) - crhs1);
        rLocalRHS[22]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(0,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(0,1), 2)) + crhs17*crhs20) - crhs4);
        rLocalRHS[23]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(0,0)*NormalSlave(0,2)*crhs20 + NormalSlave(0,1)*NormalSlave(0,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(0,2), 2))) - crhs6);
    }

    // NODE 1
    if (r_geometry[1].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[1];

        rLocalRHS[24]+=-LM(1,0)*crhs0;
        rLocalRHS[25]+=-LM(1,1)*crhs0;
        rLocalRHS[26]+=-LM(1,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(1,0)*(DOperator(1,0)*(X1(0,0) + u1(0,0)) + DOperator(1,1)*(X1(1,0) + u1(1,0)) + DOperator(1,2)*(X1(2,0) + u1(2,0)) + DOperator(1,3)*(X1(3,0) + u1(3,0)) - MOperator(1,0)*(X2(0,0) + u2(0,0)) - MOperator(1,1)*(X2(1,0) + u2(1,0)) - MOperator(1,2)*(X2(2,0) + u2(2,0))) + NormalSlave(1,1)*(DOperator(1,0)*(X1(0,1) + u1(0,1)) + DOperator(1,1)*(X1(1,1) + u1(1,1)) + DOperator(1,2)*(X1(2,1) + u1(2,1)) + DOperator(1,3)*(X1(3,1) + u1(3,1)) - MOperator(1,0)*(X2(0,1) + u2(0,1)) - MOperator(1,1)*(X2(1,1) + u2(1,1)) - MOperator(1,2)*(X2(2,1) + u2(2,1))) + NormalSlave(1,2)*(DOperator(1,0)*(X1(0,2) + u1(0,2)) + DOperator(1,1)*(X1(1,2) + u1(1,2)) + DOperator(1,2)*(X1(2,2) + u1(2,2)) + DOperator(1,3)*(X1(3,2) + u1(3,2)) - MOperator(1,0)*(X2(0,2) + u2(0,2)) - MOperator(1,1)*(X2(1,2) + u2(1,2)) - MOperator(1,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(1,0)*crhs0;
        const double crhs2 =     LM(1,0)*ScaleFactor - PenaltyParameter[1]*crhs1;
        const double crhs3 =     DynamicFactor[1]*MOperator(1,0);
        const double crhs4 =     NormalSlave(1,1)*crhs0;
        const double crhs5 =     LM(1,1)*ScaleFactor - PenaltyParameter[1]*crhs4;
        const double crhs6 =     NormalSlave(1,2)*crhs0;
        const double crhs7 =     LM(1,2)*ScaleFactor - PenaltyParameter[1]*crhs6;
        const double crhs8 =     DynamicFactor[1]*MOperator(1,1);
        const double crhs9 =     DynamicFactor[1]*MOperator(1,2);
        const double crhs10 =     DOperator(1,0)*DynamicFactor[1];
        const double crhs11 =     DOperator(1,1)*DynamicFactor[1];
        const double crhs12 =     DOperator(1,2)*DynamicFactor[1];
        const double crhs13 =     DOperator(1,3)*DynamicFactor[1];
        const double crhs14 =     1.0/PenaltyParameter[1];
        const double crhs15 =     LM(1,0)*NormalSlave(1,0) + LM(1,1)*NormalSlave(1,1) + LM(1,2)*NormalSlave(1,2);
        const double crhs16 =     LM(1,1) - NormalSlave(1,1)*crhs15;
        const double crhs17 =     NormalSlave(1,0)*NormalSlave(1,1);
        const double crhs18 =     LM(1,2) - NormalSlave(1,2)*crhs15;
        const double crhs19 =     NormalSlave(1,2)*crhs18;
        const double crhs20 =     LM(1,0) - NormalSlave(1,0)*crhs15;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[24]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(1,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(1,0), 2))) - crhs1);
        rLocalRHS[25]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(1,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(1,1), 2)) + crhs17*crhs20) - crhs4);
        rLocalRHS[26]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(1,0)*NormalSlave(1,2)*crhs20 + NormalSlave(1,1)*NormalSlave(1,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(1,2), 2))) - crhs6);
    }

    // NODE 2
    if (r_geometry[2].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[2];

        rLocalRHS[27]+=-LM(2,0)*crhs0;
        rLocalRHS[28]+=-LM(2,1)*crhs0;
        rLocalRHS[29]+=-LM(2,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(2,0)*(DOperator(2,0)*(X1(0,0) + u1(0,0)) + DOperator(2,1)*(X1(1,0) + u1(1,0)) + DOperator(2,2)*(X1(2,0) + u1(2,0)) + DOperator(2,3)*(X1(3,0) + u1(3,0)) - MOperator(2,0)*(X2(0,0) + u2(0,0)) - MOperator(2,1)*(X2(1,0) + u2(1,0)) - MOperator(2,2)*(X2(2,0) + u2(2,0))) + NormalSlave(2,1)*(DOperator(2,0)*(X1(0,1) + u1(0,1)) + DOperator(2,1)*(X1(1,1) + u1(1,1)) + DOperator(2,2)*(X1(2,1) + u1(2,1)) + DOperator(2,3)*(X1(3,1) + u1(3,1)) - MOperator(2,0)*(X2(0,1) + u2(0,1)) - MOperator(2,1)*(X2(1,1) + u2(1,1)) - MOperator(2,2)*(X2(2,1) + u2(2,1))) + NormalSlave(2,2)*(DOperator(2,0)*(X1(0,2) + u1(0,2)) + DOperator(2,1)*(X1(1,2) + u1(1,2)) + DOperator(2,2)*(X1(2,2) + u1(2,2)) + DOperator(2,3)*(X1(3,2) + u1(3,2)) - MOperator(2,0)*(X2(0,2) + u2(0,2)) - MOperator(2,1)*(X2(1,2) + u2(1,2)) - MOperator(2,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(2,0)*crhs0;
        const double crhs2 =     LM(2,0)*ScaleFactor - PenaltyParameter[2]*crhs1;
        const double crhs3 =     DynamicFactor[2]*MOperator(2,0);
        const double crhs4 =     NormalSlave(2,1)*crhs0;
        const double crhs5 =     LM(2,1)*ScaleFactor - PenaltyParameter[2]*crhs4;
        const double crhs6 =     NormalSlave(2,2)*crhs0;
        const double crhs7 =     LM(2,2)*ScaleFactor - PenaltyParameter[2]*crhs6;
        const double crhs8 =     DynamicFactor[2]*MOperator(2,1);
        const double crhs9 =     DynamicFactor[2]*MOperator(2,2);
        const double crhs10 =     DOperator(2,0)*DynamicFactor[2];
        const double crhs11 =     DOperator(2,1)*DynamicFactor[2];
        const double crhs12 =     DOperator(2,2)*DynamicFactor[2];
        const double crhs13 =     DOperator(2,3)*DynamicFactor[2];
        const double crhs14 =     1.0/PenaltyParameter[2];
        const double crhs15 =     LM(2,0)*NormalSlave(2,0) + LM(2,1)*NormalSlave(2,1) + LM(2,2)*NormalSlave(2,2);
        const double crhs16 =     LM(2,1) - NormalSlave(2,1)*crhs15;
        const double crhs17 =     NormalSlave(2,0)*NormalSlave(2,1);
        const double crhs18 =     LM(2,2) - NormalSlave(2,2)*crhs15;
        const double crhs19 =     NormalSlave(2,2)*crhs18;
        const double crhs20 =     LM(2,0) - NormalSlave(2,0)*crhs15;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[27]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(2,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(2,0), 2))) - crhs1);
        rLocalRHS[28]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(2,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(2,1), 2)) + crhs17*crhs20) - crhs4);
        rLocalRHS[29]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(2,0)*NormalSlave(2,2)*crhs20 + NormalSlave(2,1)*NormalSlave(2,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(2,2), 2))) - crhs6);
    }

    // NODE 3
    if (r_geometry[3].IsNot(ACTIVE)) { // INACTIVE
        const double crhs0 =     std::pow(ScaleFactor, 2)/PenaltyParameter[3];

        rLocalRHS[30]+=-LM(3,0)*crhs0;
        rLocalRHS[31]+=-LM(3,1)*crhs0;
        rLocalRHS[32]+=-LM(3,2)*crhs0;
    } else { // ACTIVE
        const double crhs0 =     NormalSlave(3,0)*(DOperator(3,0)*(X1(0,0) + u1(0,0)) + DOperator(3,1)*(X1(1,0) + u1(1,0)) + DOperator(3,2)*(X1(2,0) + u1(2,0)) + DOperator(3,3)*(X1(3,0) + u1(3,0)) - MOperator(3,0)*(X2(0,0) + u2(0,0)) - MOperator(3,1)*(X2(1,0) + u2(1,0)) - MOperator(3,2)*(X2(2,0) + u2(2,0))) + NormalSlave(3,1)*(DOperator(3,0)*(X1(0,1) + u1(0,1)) + DOperator(3,1)*(X1(1,1) + u1(1,1)) + DOperator(3,2)*(X1(2,1) + u1(2,1)) + DOperator(3,3)*(X1(3,1) + u1(3,1)) - MOperator(3,0)*(X2(0,1) + u2(0,1)) - MOperator(3,1)*(X2(1,1) + u2(1,1)) - MOperator(3,2)*(X2(2,1) + u2(2,1))) + NormalSlave(3,2)*(DOperator(3,0)*(X1(0,2) + u1(0,2)) + DOperator(3,1)*(X1(1,2) + u1(1,2)) + DOperator(3,2)*(X1(2,2) + u1(2,2)) + DOperator(3,3)*(X1(3,2) + u1(3,2)) - MOperator(3,0)*(X2(0,2) + u2(0,2)) - MOperator(3,1)*(X2(1,2) + u2(1,2)) - MOperator(3,2)*(X2(2,2) + u2(2,2)));
        const double crhs1 =     NormalSlave(3,0)*crhs0;
        const double crhs2 =     LM(3,0)*ScaleFactor - PenaltyParameter[3]*crhs1;
        const double crhs3 =     DynamicFactor[3]*MOperator(3,0);
        const double crhs4 =     NormalSlave(3,1)*crhs0;
        const double crhs5 =     LM(3,1)*ScaleFactor - PenaltyParameter[3]*crhs4;
        const double crhs6 =     NormalSlave(3,2)*crhs0;
        const double crhs7 =     LM(3,2)*ScaleFactor - PenaltyParameter[3]*crhs6;
        const double crhs8 =     DynamicFactor[3]*MOperator(3,1);
        const double crhs9 =     DynamicFactor[3]*MOperator(3,2);
        const double crhs10 =     DOperator(3,0)*DynamicFactor[3];
        const double crhs11 =     DOperator(3,1)*DynamicFactor[3];
        const double crhs12 =     DOperator(3,2)*DynamicFactor[3];
        const double crhs13 =     DOperator(3,3)*DynamicFactor[3];
        const double crhs14 =     1.0/PenaltyParameter[3];
        const double crhs15 =     LM(3,0)*NormalSlave(3,0) + LM(3,1)*NormalSlave(3,1) + LM(3,2)*NormalSlave(3,2);
        const double crhs16 =     LM(3,1) - NormalSlave(3,1)*crhs15;
        const double crhs17 =     NormalSlave(3,0)*NormalSlave(3,1);
        const double crhs18 =     LM(3,2) - NormalSlave(3,2)*crhs15;
        const double crhs19 =     NormalSlave(3,2)*crhs18;
        const double crhs20 =     LM(3,0) - NormalSlave(3,0)*crhs15;

        rLocalRHS[0]+=-crhs2*crhs3;
        rLocalRHS[1]+=-crhs3*crhs5;
        rLocalRHS[2]+=-crhs3*crhs7;
        rLocalRHS[3]+=-crhs2*crhs8;
        rLocalRHS[4]+=-crhs5*crhs8;
        rLocalRHS[5]+=-crhs7*crhs8;
        rLocalRHS[6]+=-crhs2*crhs9;
        rLocalRHS[7]+=-crhs5*crhs9;
        rLocalRHS[8]+=-crhs7*crhs9;
        rLocalRHS[9]+=crhs10*crhs2;
        rLocalRHS[10]+=crhs10*crhs5;
        rLocalRHS[11]+=crhs10*crhs7;
        rLocalRHS[12]+=crhs11*crhs2;
        rLocalRHS[13]+=crhs11*crhs5;
        rLocalRHS[14]+=crhs11*crhs7;
        rLocalRHS[15]+=crhs12*crhs2;
        rLocalRHS[16]+=crhs12*crhs5;
        rLocalRHS[17]+=crhs12*crhs7;
        rLocalRHS[18]+=crhs13*crhs2;
        rLocalRHS[19]+=crhs13*crhs5;
        rLocalRHS[20]+=crhs13*crhs7;
        rLocalRHS[30]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(3,0)*crhs19 + crhs16*crhs17 - crhs20*(1 - std::pow(NormalSlave(3,0), 2))) - crhs1);
        rLocalRHS[31]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(3,1)*crhs19 - crhs16*(1 - std::pow(NormalSlave(3,1), 2)) + crhs17*crhs20) - crhs4);
        rLocalRHS[32]+=ScaleFactor*(ScaleFactor*crhs14*(NormalSlave(3,0)*NormalSlave(3,2)*crhs20 + NormalSlave(3,1)*NormalSlave(3,2)*crhs16 - crhs18*(1 - std::pow(NormalSlave(3,2), 2))) - crhs6);
    }
}

